$\quad\quad - 5 x^{10} y^{9} z^{6} $, $\quad\quad {- 5 x^{4} - 7 y^{7}} ,\quad\quad {4 x \left(5 y + 7\right)}, \quad\quad  x^{7} + 5, \quad\quad {- 5 x^{2} + 7 y^{4}} $
}\end{ex}

