L08_C4_B2_04.latex:
\begin{ex}%[8H4N2]
\immini[thm]{
Cho tam giác ${GHF}$ cân tại ${G}$ đường cao ${GJ}$ , ${I}$ là trung điểm của ${GF}$. Từ ${G}$ kẻ tia ${Gy}$ song song với ${HF}$ cắt ${JI}$ tại ${E}$ 

a) Chứng minh ${JH=JF}$.

b) Chứng minh $JE //HF$.

c) Chứng minh $GE=JF$
}{
\begin{tikzpicture}
    % Tọa độ của các điểm
    \coordinate [label=above:{$G$}] (A) at (0,3);
    \coordinate [label=below left:{$H$}] (B) at (-2,0);
    \coordinate [label=below right:{$F$}] (C) at (2,0);
    \coordinate [label=below:{$J$}] (M) at (0,0); % Trung điểm của BC
    \coordinate [label=right:{$I$}] (N) at (1,1.5); % Trung điểm của AC
    \coordinate [label=above:{$E$}] (E) at (2,3);
    % Vẽ tam giác ABC cân tại A
    \draw [thick] (B) -- (A) -- (C) -- cycle;

    % Vẽ trung điểm M của BC và N của AC
    \draw [thick] (A) -- (M);
    % Vẽ tia Ax song song với BC
    \draw [thick, ->] (A) -- ++(3,0) coordinate (X) node[above] {$y$};

    % Vẽ điểm E trên MN
    \draw [thick] (M) -- (E);
    \fill (E) circle (2pt); % Ký hiệu điểm E

    % Ký hiệu các điểm khác
    \fill (A) circle (2pt);
    \fill (B) circle (2pt);
    \fill (C) circle (2pt);
    \fill (M) circle (2pt);
    \fill (N) circle (2pt);
\end{tikzpicture}
}
\loigiai{
a) $\Delta {GHF}$ cân tại ${G}$ có ${GJ}$ vừa là đường cao cũng là trung tuyến suy ra ${JH=JF}$\\
b) $\Delta {GHF}$ có ${JH=JF}$ và  ${IG=IF}$ nên $ {JI}$ là đường trung bình suy ra $JI //GH$ hay $JE //GH$\\
Tứ giác ${GHJE}$ có $GE // HJ$, $GH // JE$ nên ${GHJE}$ là hình bình hành suy ra $GE=HJ=JF$
}\end{ex}

