\immini[thm]{
Cho biết chiếc thang của một xe cứu hỏa có chiều dài $AB = 20$ m, chân thang cách mặt đất một khoảng $BE = 2,2$ m và cách tường tòa nhà một khoảng $BC = 5$ m. Tính chiều cao $AD$ mà thang có thể vươn tới (kết quả làm tròn đến hàng phần mười).
}{
\begin{tikzpicture}[line cap=round, line join=round, scale=0.3]
    % Định nghĩa các điểm (Dùng b_val để tính toán tọa độ)
    \coordinate (E) at (0,0);
    \coordinate (D) at (5,0);
    \coordinate (B) at (0,2.2);
    \coordinate (C) at (5,2.2);
    \coordinate (A) at (5, 21.564916731037084);

    % Vẽ các đoạn thẳng
    \draw[thick] (A) -- (B) node[midway, left, xshift=-2pt] {20m};
    \draw[thick] (B) -- (C) node[midway, above] {5m};
    \draw[thick] (A) -- (D);
    \draw[thick] (B) -- (E) node[midway, left] {2,2m}; % Hiển thị dấu phẩy ở đây
    \draw[thick] (E) -- (D);

    % Ký hiệu góc vuông tại C
    \draw (4.2, 2.2) -- (4.2, 3.0) -- (5, 3.0);

    % Gán nhãn các đỉnh
    \node[above] at (A) {$A$};
    \node[left] at (B) {$B$};
    \node[right] at (C) {$C$};
    \node[below] at (D) {$D$};
    \node[below] at (E) {$E$};
\end{tikzpicture}
}
\loigiai{
