\immini[thm]{
Cho $\triangle {IJQ}$ vuông cân tại ${I}$ có đường cao ${IE}$.

 a) Chứng minh $\triangle {EJI}\backsim\triangle {IJQ}$ Từ đó suy ra $IJ^{2}=JE\cdot JQ$.

 b)  Gọi ${M}$, ${N}$ lần lượt là trung điểm của ${IJ}$ và ${IQ}$. Chứng minh tứ giác ${JMNQ}$ là hình thang cân và $MN=IE$.

 c) Gọi ${F}$ là giao điểm của ${IE}$ và ${QM}$. Chứng minh $JQ=3IF$.
}{
\begin{tikzpicture}[line join = round, line cap=round,>=stealth,font=\footnotesize,scale=1]
    \path 
    (0,0) coordinate (A)
    (6,0) coordinate (C)
    (0,6) coordinate (B)
    ($(C)!(A)!(B)$) coordinate (H)
    ($(A)!.5!(B)$) coordinate (M)
    ($(A)!.5!(C)$) coordinate (N)
    (intersection of A--H and C--M) coordinate (K)
    ;

    \draw 
    (A)--(B)--(C)--(A)--(H) (M)--(N) (C)--(M) (B)--(M)node[midway]{$-$}--(A)node[midway]{$-$} (A)--(N)node[midway,scale=0.7]{$|$}--(C)node[midway,scale=0.7]{$|$}
    ;
    \draw   pic[draw, angle radius=0.5cm] {right angle=C--A--B};
    \draw   pic[draw, angle radius=.5cm] {right angle=A--H--C} ;
     \filldraw[black] (A) circle (2pt) node[above left] {$I$};
    \filldraw[black] (B) circle (2pt) node[above left] {$J$};
    \filldraw[black] (C) circle (2pt) node[above] {$Q$};
   \filldraw[black] (M) circle (2pt) node[above left]{$M$};
    \filldraw[black] (N) circle (2pt) node[below left] {$N$};
    \filldraw[black] (H) circle (2pt) node[above] {$E$};
     \filldraw[black] (K) circle (2pt) node[above] {$F$};
\end{tikzpicture}
}
\loigiai{
a) Xét $\triangle {EJI}$ và $\triangle {IJQ}$ có\\
$\widehat{IEJ}=\widehat{JIQ}=90^{\circ}$\\
$\widehat{IJQ} $ chung.\\
Suy ra $\triangle EJI\backsim\triangle IJQ$ (g.g).\\
Suy ra $\dfrac{IJ}{JQ}=\dfrac{JE}{IJ}$.\\
Suy ra $IJ^{2}=JE\cdot JQ$ (đpcm).\\
b) Vì ${M}$, ${N}$ lần lượt là trung điểm của $IJ$ và $IQ$.\\
Suy ra $MN$ là đường trung bình của tam giác $IJQ$.\\
Suy ra $ MN\parallel JQ$ và $MN=\dfrac{1}{2}JQ$.\\
Vì tam giác $IJQ$ vuông cân tại ${I}$, suy ra $\widehat{IJQ}=\widehat{IQJ}=45^{\circ}$.\\
Xét tứ giác $JMNQ$ có $MN\parallel JQ$ và  $\widehat{IJQ}=\widehat{IQJ}$ suy ra tứ giác $JMNQ$ là hình thang cân.\\
Vì tam giác $IJQ$ vuông cân tại ${I}$, $IE$ là đường cao.\\
Suy ra $IE$ là đường trung tuyến và ${E}$ là trung điểm của $JQ$.\\
Suy ra $IE=\dfrac{JQ}{2}$ (đường trung tuyến ứng cạnh huyền trong tam giác vuông).\\
Mà $MN\parallel JQ$ (cmt)\\
Suy ra $MN=IE$ (đpcm).\\
c) Có ${F}$ là giao điểm của hai đường trung tuyến $IE$ và $QM$.\\
Suy ra ${F}$ là trọng tâm tam giác $IJQ$.\\
Suy ra $IF=\dfrac{2}{3}IE$, mà $IE=\dfrac{JQ}{2}$.\\
Suy ra $IF=\dfrac{2}{3}\cdot\dfrac{JQ}{2}=\dfrac{JQ}{3}$.\\
Suy ra $JQ=3IF$ (đpcm).
}\end{ex}

\begin{ex}%[8H9V6]
\immini[thm]{
Cho $\triangle {ABC}$ vuông cân tại ${A}$ có đường cao ${AM}$.

 a) Chứng minh $\triangle {MBA}\backsim\triangle {ABC}$ Từ đó suy ra $AB^{2}=BM\cdot BC$.

 b)  Gọi ${I}$, ${J}$ lần lượt là trung điểm của ${AB}$ và ${AC}$. Chứng minh tứ giác ${BIJC}$ là hình thang cân và $IJ=AM$.

 c) Gọi ${N}$ là giao điểm của ${AM}$ và ${CI}$. Chứng minh $BC=3AN$.
}{
\begin{tikzpicture}[line join = round, line cap=round,>=stealth,font=\footnotesize,scale=1]
    \path 
    (0,0) coordinate (A)
    (6,0) coordinate (C)
    (0,6) coordinate (B)
    ($(C)!(A)!(B)$) coordinate (H)
    ($(A)!.5!(B)$) coordinate (M)
    ($(A)!.5!(C)$) coordinate (N)
    (intersection of A--H and C--M) coordinate (K)
    ;

    \draw 
    (A)--(B)--(C)--(A)--(H) (M)--(N) (C)--(M) (B)--(M)node[midway]{$-$}--(A)node[midway]{$-$} (A)--(N)node[midway,scale=0.7]{$|$}--(C)node[midway,scale=0.7]{$|$}
    ;
    \draw   pic[draw, angle radius=0.5cm] {right angle=C--A--B};
    \draw   pic[draw, angle radius=.5cm] {right angle=A--H--C} ;
     \filldraw[black] (A) circle (2pt) node[above left] {$A$};
    \filldraw[black] (B) circle (2pt) node[above left] {$B$};
    \filldraw[black] (C) circle (2pt) node[above] {$C$};
   \filldraw[black] (M) circle (2pt) node[above left]{$I$};
    \filldraw[black] (N) circle (2pt) node[below left] {$J$};
    \filldraw[black] (H) circle (2pt) node[above] {$M$};
     \filldraw[black] (K) circle (2pt) node[above] {$N$};
\end{tikzpicture}
}
\loigiai{
a) Xét $\triangle {MBA}$ và $\triangle {ABC}$ có\\
$\widehat{AMB}=\widehat{BAC}=90^{\circ}$\\
$\widehat{ABC} $ chung.\\
Suy ra $\triangle MBA\backsim\triangle ABC$ (g.g).\\
Suy ra $\dfrac{AB}{BC}=\dfrac{BM}{AB}$.\\
Suy ra $AB^{2}=BM\cdot BC$ (đpcm).\\
b) Vì ${I}$, ${J}$ lần lượt là trung điểm của $AB$ và $AC$.\\
Suy ra $IJ$ là đường trung bình của tam giác $ABC$.\\
Suy ra $ IJ\parallel BC$ và $IJ=\dfrac{1}{2}BC$.\\
Vì tam giác $ABC$ vuông cân tại ${A}$, suy ra $\widehat{ABC}=\widehat{ACB}=45^{\circ}$.\\
Xét tứ giác $BIJC$ có $IJ\parallel BC$ và  $\widehat{ABC}=\widehat{ACB}$ suy ra tứ giác $BIJC$ là hình thang cân.\\
Vì tam giác $ABC$ vuông cân tại ${A}$, $AM$ là đường cao.\\
Suy ra $AM$ là đường trung tuyến và ${M}$ là trung điểm của $BC$.\\
Suy ra $AM=\dfrac{BC}{2}$ (đường trung tuyến ứng cạnh huyền trong tam giác vuông).\\
Mà $IJ\parallel BC$ (cmt)\\
Suy ra $IJ=AM$ (đpcm).\\
c) Có ${N}$ là giao điểm của hai đường trung tuyến $AM$ và $CI$.\\
Suy ra ${N}$ là trọng tâm tam giác $ABC$.\\
Suy ra $AN=\dfrac{2}{3}AM$, mà $AM=\dfrac{BC}{2}$.\\
Suy ra $AN=\dfrac{2}{3}\cdot\dfrac{BC}{2}=\dfrac{BC}{3}$.\\
Suy ra $BC=3AN$ (đpcm).
}\end{ex}
